import { ConvexReactClient } from "convex/react";
import { api } from "../../convex/_generated/api";

/**
 * Rebirth Convex client (Phase 3).
 *
 * Single client instance shared across the app. Reads/writes go through the
 * typed function references in `api` (generated by `npx convex codegen`).
 *
 * Auth model (per ADR-001):
 * - Every synced row carries `userId`.
 * - Guest mode: no userId → data stays in localStorage only (never written to Convex).
 * - Authenticated mode: userId bound → data written to Convex with ownership enforced
 *   in Convex functions (RLS-equivalent).
 *
 * VITE_CONVEX_URL is injected at build time by `npx convex dev` (.env.local,
 * gitignored). Never commit the deployment URL with credentials.
 */
const convexUrl = (import.meta as any).env?.VITE_CONVEX_URL;

if (!convexUrl) {
  // eslint-disable-next-line no-console
  console.warn(
    "[Rebirth] VITE_CONVEX_URL not set. Convex sync disabled. Guest/localStorage mode active.",
  );
}

export const convex = new ConvexReactClient(convexUrl);

export type ConvexApi = typeof api;
export type ConvexFunctionNames = keyof typeof api;

export function isConvexReady(): boolean {
  return Boolean(convexUrl);
}

export { api };
